(function(){"use strict";var BUCKET="creatividades";var HTML_PERMITIDO={ALLOWED_TAGS:["b","i","em","strong","br","span"],ALLOWED_ATTR:["class"]};function sb(){if(!window.LW_AUTH)return Promise.reject(new Error("Sin sesión: falta guard.js en esta página."));return window.LW_AUTH.then((function(a){return a.sb}))}function falla(r){if(r&&r.error)throw r.error;return r?r.data:null}function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,(function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]}))}function limpia(html){if(window.DOMPurify&&window.DOMPurify.sanitize)return window.DOMPurify.sanitize(String(html==null?"":html),HTML_PERMITIDO);return esc(html)}function limpiaEstado(v){if(typeof v==="string")return limpia(v);if(Array.isArray(v))return v.map(limpiaEstado);if(v&&typeof v==="object"){var o={};Object.keys(v).forEach((function(k){o[k]=limpiaEstado(v[k])}));return o}return v}function subeCreatividad(c,id,tipo,rol,blob){return window.lwFichero(c,"creatividad","subida_url",{creatividad_id:id||null,tipo:tipo,rol:rol}).then((function(u){var f=new File([blob],rol+(rol==="estado"?".json":".png"),{type:u.content_type});return c.storage.from(u.bucket).uploadToSignedUrl(u.path,u.token,f,{contentType:u.content_type}).then((function(up){if(up.error)throw new Error("No se pudo subir el fichero: "+(up.error.message||up.error));return u}))}))}async function guardar(o){if(typeof window.lwFichero!=="function")throw new Error("Falta guard.js actualizado: recarga la página");var c=await sb();var datos={titulo:String(o.titulo||"").trim().slice(0,200)||"Sin título",proyecto_id:o.proyecto_id||null,formato:o.formato||null,arquetipo:o.arquetipo||null,precios_a:o.precios_a||null};var est=await subeCreatividad(c,o.id,o.tipo,"estado",new Blob([JSON.stringify(o.estado||{})],{type:"application/json"}));var id=est.creatividad_id;var cuerpo={creatividad_id:id,tipo:o.tipo,datos:datos,estado_path:est.path};if(o.png)cuerpo.path=(await subeCreatividad(c,id,o.tipo,"pieza",o.png)).path;if(o.portada)cuerpo.portada_path=(await subeCreatividad(c,id,o.tipo,"portada",o.portada)).path;if(o.fotoIds)cuerpo.foto_ids=uniq(o.fotoIds);if(o.modeloIds)cuerpo.modelo_ids=uniq(o.modeloIds);var r=await window.lwFichero(c,"creatividad","guarda",cuerpo);return r.fila}function uniq(a){return(a||[]).filter((function(x,i,t){return x&&t.indexOf(x)===i}))}async function abrir(id){var c=await sb();var fila=falla(await c.from("creatividades").select("*").eq("id",id).single());if(!fila.estado_path)return{fila:fila,estado:null};var blob=falla(await c.storage.from(BUCKET).download(fila.estado_path));var txt=await blob.text();var estado;try{estado=JSON.parse(txt)}catch(e){throw new Error("El estado guardado no es un JSON válido.")}if(!estado||typeof estado!=="object"||Array.isArray(estado))throw new Error("El estado guardado no tiene la forma esperada.");return{fila:fila,estado:limpiaEstado(estado)}}async function listar(filtro){var c=await sb();var q=c.from("creatividades").select("id, tipo, titulo, proyecto_id, formato, arquetipo, estado, path, estado_path, portada_path, lleva_render, precios_a, origen, creado_por, creado_en, actualizado_en, enviada_por, enviada_en, aprobada_en, publicada_en, archivada_en").order("creado_en",{ascending:false}).limit(500);if(filtro&&filtro.tipo)q=q.eq("tipo",filtro.tipo);if(filtro&&filtro.estado)q=q.eq("estado",filtro.estado);if(filtro&&filtro.proyecto_id)q=q.eq("proyecto_id",filtro.proyecto_id);return falla(await q)||[]}async function cambiarEstado(id,estado){var c=await sb();return falla(await c.rpc("creatividad_estado",{p_id:id,p_estado:estado}))}async function urlDescarga(id,fichero,nombre){var c=await sb();falla(await c.rpc("creatividad_descarga",{p_id:id,p_fichero:fichero}));var r=falla(await c.storage.from(BUCKET).createSignedUrl(fichero,120,nombre?{download:nombre}:undefined));return r.signedUrl}async function urlVer(fichero){var c=await sb();var r=falla(await c.storage.from(BUCKET).createSignedUrl(fichero,300));return r.signedUrl}async function fotos(filtro){var c=await sb();var q=c.from("deck_fotos").select("id, ambito, proyecto_id, modelo_id, tipo, uso, path, pie, orden").order("orden",{ascending:true}).limit(1e3);if(filtro&&filtro.proyecto_id)q=q.eq("proyecto_id",filtro.proyecto_id);if(filtro&&filtro.modelo_id)q=q.eq("modelo_id",filtro.modelo_id);if(filtro&&filtro.ambito)q=q.eq("ambito",filtro.ambito);var filas=falla(await q)||[];return filas.map((function(f){f.url=c.storage.from("deck").getPublicUrl(f.path).data.publicUrl;f.esRender=f.tipo!=="foto";f.rotulo=f.pie&&(f.pie.es||f.pie.en)||"";return f}))}async function urlFoto(fotoId){var c=await sb();var f=falla(await c.from("deck_fotos").select("path").eq("id",fotoId).maybeSingle());return f?c.storage.from("deck").getPublicUrl(f.path).data.publicUrl:null}async function bloqueLegal(clave,idioma){var c=await sb();var r=falla(await c.from("bloques_legales").select("texto, version, estado").eq("clave",clave).eq("idioma",idioma==="es"?"es":"en").order("version",{ascending:false}).limit(1));return r&&r[0]||null}var ESTADOS={borrador:"Borrador",pendiente:"Para aprobar",aprobada:"Aprobada",publicada:"Publicada",archivada:"Archivada"};window.lwCreatividades={guardar:guardar,abrir:abrir,listar:listar,cambiarEstado:cambiarEstado,urlDescarga:urlDescarga,urlVer:urlVer,fotos:fotos,urlFoto:urlFoto,bloqueLegal:bloqueLegal,limpia:limpia,limpiaEstado:limpiaEstado,ESTADOS:ESTADOS}})();